  let t = clamp((input.scalar - s.params.x) * s.params.y, 0.0, 1.0);
  var color: vec3<f32>;
  if (s.extra.x > 0.5) {
    color = clamp(magma(t), vec3<f32>(0.0), vec3<f32>(1.0));
  } else {
    color = clamp(viridis(t), vec3<f32>(0.0), vec3<f32>(1.0));
  }
